/* eslint-disable no-restricted-globals */
/**
 * EgyKode service worker.
 *
 * Offline is a CACHE OF CANONICAL CONTENT, never a second source of truth. Every
 * response here was fetched from the site; nothing is bundled, and nothing is
 * authored in this file. When the network is available the cache is refreshed
 * from it, so a chapter correction reaches an installed Windows app on the next
 * visit without a Store submission.
 *
 * Written by hand rather than generated by Workbox for one reason: the site is a
 * static export of ~300 pages and 35 MB of HTML. A generated precache manifest
 * would either bundle all of it into the install, which the brief explicitly
 * rules out, or need enough configuration that the tool stops saving work.
 *
 * Three behaviours, chosen per request type:
 *
 *   app shell + assets   cache-first      immutable, fingerprinted, ~1.4 MB
 *   pages (HTML)         network-first    always current when online, readable offline
 *   everything else      stale-while-revalidate
 */

const VERSION = "v1";
const SHELL = `egykode-shell-${VERSION}`;
const PAGES = `egykode-pages-${VERSION}`;
const ASSETS = `egykode-assets-${VERSION}`;
const CURRENT = new Set([SHELL, PAGES, ASSETS]);

/**
 * The smallest set that makes the app open offline at all.
 *
 * Deliberately not the curriculum. A learner who installs and immediately goes
 * offline gets a working shell and an honest message, not 35 MB downloaded
 * behind their back on a metered connection.
 */
const SHELL_URLS = ["/en/", "/en/learn/", "/en/labs/", "/offline/", "/icons/icon-192.png"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL)
      .then((cache) => cache.addAll(SHELL_URLS))
      // A shell URL that 404s must not abandon the whole installation; the app
      // still works, it just opens online-only.
      .catch(() => undefined)
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => !CURRENT.has(k)).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

/** Pages are HTML navigations; everything else is an asset. */
const isPage = (request) => request.mode === "navigate";
const isImmutable = (url) => url.pathname.startsWith("/_next/static/");

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Never touch anything but same-origin GETs. A cached POST is a bug, and
  // caching another origin's response is not this worker's business.
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (isPage(request)) {
    event.respondWith(networkFirst(request));
    return;
  }
  if (isImmutable(url)) {
    event.respondWith(cacheFirst(request, ASSETS));
    return;
  }
  event.respondWith(staleWhileRevalidate(request, ASSETS));
});

/**
 * Pages: try the network, fall back to the cache, then to the offline page.
 *
 * Network-first rather than cache-first because a stale chapter is the failure
 * this whole architecture exists to prevent. Online, the learner always sees
 * what the site currently says.
 */
async function networkFirst(request) {
  const cache = await caches.open(PAGES);
  try {
    const response = await fetch(request);
    if (response && response.ok) cache.put(request, response.clone());
    return response;
  } catch {
    const cached = await cache.match(request);
    if (cached) return cached;
    const offline = await caches.match("/offline/");
    return (
      offline ??
      new Response("You are offline, and this page has not been saved yet.", {
        status: 503,
        headers: { "Content-Type": "text/plain; charset=utf-8" },
      })
    );
  }
}

/** Fingerprinted assets never change under the same URL, so the cache wins. */
async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response && response.ok) (await caches.open(cacheName)).put(request, response.clone());
  return response;
}

/** Everything else: serve what we have, refresh in the background. */
async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response && response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  return cached ?? (await network) ?? Response.error();
}

/**
 * "Save for offline" — an explicit, visible download.
 *
 * The page sends a list of canonical URLs; this fetches them into the page
 * cache and reports progress. It exists so offline reading is something the
 * learner chooses, on a connection they know about, rather than something the
 * app does to them at install time.
 */
self.addEventListener("message", (event) => {
  const data = event.data;
  if (!data || data.type !== "egykode:save-offline") return;

  event.waitUntil(
    (async () => {
      const cache = await caches.open(PAGES);
      const urls = Array.isArray(data.urls) ? data.urls : [];
      let done = 0;
      for (const url of urls) {
        try {
          const response = await fetch(url, { cache: "reload" });
          if (response && response.ok) await cache.put(url, response.clone());
        } catch {
          // One unreachable page must not abandon the rest of the download.
        }
        done += 1;
        event.source?.postMessage({ type: "egykode:save-progress", done, total: urls.length });
      }
      event.source?.postMessage({ type: "egykode:save-complete", done, total: urls.length });
    })(),
  );
});
